const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const punjab = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.eq('ADM1_NAME', 'Punjab'))
      .geometry();
    const haryana = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.eq('ADM1_NAME', 'Haryana'))
      .geometry();
    const roi = punjab.union(haryana);

    const start2022 = '2022-11-01';
    const end2022 = '2022-11-30';
    const start2024 = '2024-11-01';
    const end2024 = '2024-11-30';

    const viirsCollection = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGTDL_NRT');

    // 2. Data Acquisition & Check
    const fires2022 = viirsCollection
      .filterDate(start2022, end2022)
      .filterBounds(roi);

    const fires2024 = viirsCollection
      .filterDate(start2024, end2024)
      .filterBounds(roi);

    const size2022 = await fires2022.size().getInfo();
    const size2024 = await fires2024.size().getInfo();

    if (size2022 === 0 || size2024 === 0) {
      console.log(`2022 Images: ${size2022}, 2024 Images: ${size2024}`);
      console.log('C1');
      return;
    }

    // 3. Processing: Filter for high confidence fires and count pixels
    // High confidence fires typically have confidence >= 80
    // The VNP14IMGTDL_NRT product has a 'confidence' band (0-100)
    const highConfidenceFires2022 = fires2022
      .select('confidence')
      .map(image => image.updateMask(image.gte(80))); // Mask pixels with confidence < 80

    const highConfidenceFires2024 = fires2024
      .select('confidence')
      .map(image => image.updateMask(image.gte(80))); // Mask pixels with confidence < 80

    // Mosaic and count pixels to get total active fire detections for the period
    const fireCountImage2022 = highConfidenceFires2022.count().rename('fire_pixels');
    const fireCountImage2024 = highConfidenceFires2024.count().rename('fire_pixels');

    // Use a large scale for regional summary to prevent memory issues
    const scale = 1000; 

    const reducer = ee.Reducer.sum();

    const firePixels2022Result = await fireCountImage2022.reduceRegion({
      reducer: reducer,
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).get('fire_pixels').getInfo();

    const firePixels2024Result = await fireCountImage2024.reduceRegion({
      reducer: reducer,
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).get('fire_pixels').getInfo();

    if (firePixels2022Result === null || isNaN(firePixels2022Result) ||
        firePixels2024Result === null || isNaN(firePixels2024Result)) {
      console.log('C3');
      return;
    }

    const totalFires2022 = firePixels2022Result;
    const totalFires2024 = firePixels2024Result;

    console.log(`2022 Images: ${size2022}, 2024 Images: ${size2024}`);
    console.log(`Total active fire pixels (high confidence) in Nov 2022: ${totalFires2022}`);
    console.log(`Total active fire pixels (high confidence) in Nov 2024: ${totalFires2024}`);

    // Check for C2: No valid pixels after masking
    if (totalFires2022 === 0 && size2022 > 0) {
      console.log('No valid fire pixels found in 2022 after filtering.');
    }
    if (totalFires2024 === 0 && size2024 > 0) {
      console.log('No valid fire pixels found in 2024 after filtering.');
    }
    if (totalFires2022 === 0 && totalFires2024 === 0) { // If both are 0, it means no fires, which is a valid result.
      console.log('A'); // If 0, then 0 is not lower than 0, but the question is "lower than". So A
      return;
    }

    // 5. Validation & Final Answer
    if (totalFires2024 < totalFires2022) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (error) {
    console.error("An error occurred: ", error);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
